code_constraint:
(productName != null && !productName.isBlank()) ? switch (productName) {
case "PostgreSQL" -> new PostgresJdbcStoreDialect();
case "MySQL", "MariaDB" -> new MysqlJdbcStoreDialect();
case "SQLite" -> new SqliteJdbcStoreDialect();
case "H2" -> new H2JdbcStoreDialect();
default -> {
LOG.warn(
    "Unrecognised JDBC database product '{}'; defaulting to Postgres dialect",
productName);
new PostgresJdbcStoreDialect();
}
} : new PostgresJdbcStoreDialect();

(Assert.notNull(toolSpecifications, "Tool handlers list must not be null") && 
toolSpecifications.stream()
.allMatch(tool -> {
    String toolName = tool.tool().name();
    validateToolName(toolName) &&
    assertNoDuplicateTool(toolName);
}))
